choose.when:
SELECT id, tenant_id, snapshot_year, snapshot_month, item_key, status, score
FROM activity_snapshot
WHERE tenant_id = #{tenantId}
  AND snapshot_year = #{startYear}
  AND snapshot_month BETWEEN #{startMonth} AND #{endMonth}

choose.otherwise:
SELECT id, tenant_id, snapshot_year, snapshot_month, item_key, status, score
FROM activity_snapshot
WHERE tenant_id = #{tenantId}
  AND snapshot_year = #{startYear}
  AND snapshot_month >= #{startMonth}

UNION ALL

SELECT id, tenant_id, snapshot_year, snapshot_month, item_key, status, score
FROM activity_snapshot
WHERE tenant_id = #{tenantId}
  AND snapshot_year > #{startYear}
  AND snapshot_year < #{endYear}

UNION ALL

SELECT id, tenant_id, snapshot_year, snapshot_month, item_key, status, score
FROM activity_snapshot
WHERE tenant_id = #{tenantId}
  AND snapshot_year = #{endYear}
  AND snapshot_month <= #{endMonth}
